package ua.malinapk.birthdays;

import android.app.*;
import android.app.job.*;
import android.content.*;
import android.security.keystore.*;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.KeyStore;
import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

final class Telegram {
 static final String ACTION="ua.malinapk.birthdays.TELEGRAM", ALIAS="birthday_telegram_token";
 static final int MONTH=-1, JOB=793145;
 static final Object DELIVERY_LOCK=new Object();
 static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd.MM");
 static SharedPreferences p(Context c){return c.getSharedPreferences("telegram_reminders",0);}
 static boolean flag(Context c,String key){return p(c).getBoolean(key,true);}
 static boolean connected(Context c){return !p(c).getString("chat","").isEmpty()&&!p(c).getString("secret","").isEmpty();}
 static String group(Context c){return p(c).getString("group","");}
 static List<Integer> rules(Context c){List<Integer> out=new ArrayList<>();for(String s:p(c).getString("rules","0,1,2").split(","))try{int id=Integer.parseInt(s);if(id>=0&&!out.contains(id))out.add(id);}catch(Exception ignored){}return out;}
 static int offset(Context c,int id){return p(c).getInt("offset"+id,id<=2?id:0);}
 static LocalTime time(Context c,int id){return LocalTime.of(p(c).getInt("hour"+id,8),p(c).getInt("minute"+id,0));}
 static boolean active(Context c,int id){return rules(c).contains(id)&&p(c).getBoolean("ruleOn"+id,true);}
 static void saveRule(Context c,int id,int days,LocalTime t){List<Integer> ids=rules(c);SharedPreferences.Editor e=p(c).edit();if(id<0){id=Math.max(3,p(c).getInt("next",3));ids.add(id);e.putInt("next",id+1).putString("rules",ReminderReceiver.encode(ids));}e.putInt("offset"+id,days).putInt("hour"+id,t.getHour()).putInt("minute"+id,t.getMinute()).apply();scheduleOne(c,id);}
 static void removeRule(Context c,int id){List<Integer> ids=rules(c);ids.remove(Integer.valueOf(id));p(c).edit().putString("rules",ReminderReceiver.encode(ids)).remove("offset"+id).remove("hour"+id).remove("minute"+id).remove("ruleOn"+id).remove("last"+id).apply();scheduleOne(c,id);}
 static void flag(Context c,String key,boolean value){p(c).edit().putBoolean(key,value).apply();if(!value)prune(c);schedule(c);}
 static PendingIntent alarm(Context c,int id){return PendingIntent.getBroadcast(c,id,new Intent(c,ReminderReceiver.class).setAction(ACTION).putExtra("telegramId",id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static boolean canRun(Context c,int id){return connected(c)&&flag(c,"enabled")&&(id==MONTH?flag(c,"month"):flag(c,"birthdays")&&active(c,id));}
 static void schedule(Context c){for(int id:rules(c))scheduleOne(c,id);scheduleOne(c,MONTH);if(connected(c)&&flag(c,"enabled"))kick(c);}
 static void scheduleOne(Context c,int id){AlarmManager am=c.getSystemService(AlarmManager.class);PendingIntent pi=alarm(c,id);am.cancel(pi);if(!canRun(c,id)){pi.cancel();p(c).edit().remove("planned"+id).apply();return;}LocalDateTime now=LocalDateTime.now(),next;
  if(id==MONTH){YearMonth m=YearMonth.from(now);LocalDate day=ExportFilter.standDay(m);if(now.toLocalDate().isAfter(day)||m.toString().equals(p(c).getString("lastMonth","")))day=ExportFilter.standDay(m.plusMonths(1));next=LocalDateTime.of(day,time(c,id));if(!next.isAfter(now))next=now.plusSeconds(2);}
  else {next=LocalDateTime.of(now.toLocalDate(),time(c,id));String planned=p(c).getString("planned"+id,"");if(!next.isAfter(now)){if(next.toString().equals(planned)&&!now.toLocalDate().toString().equals(p(c).getString("last"+id,"")))next=now.plusSeconds(2);else next=next.plusDays(1);}if(next.toLocalTime().equals(time(c,id)))p(c).edit().putString("planned"+id,next.toString()).apply();}
  ReminderReceiver.setAlarm(c,am,pi,next);
 }
 static void fire(Context c,int id){if(!canRun(c,id))return;LocalDate today=LocalDate.now();String key=id==MONTH?"lastMonth":"last"+id;String value=id==MONTH?YearMonth.from(today).toString():today.toString();
  if(!value.equals(p(c).getString(key,""))&&(id!=MONTH||today.equals(ExportFilter.standDay(YearMonth.from(today))))){List<Person> list=ReminderReceiver.current(c);List<Msg> msgs=new ArrayList<>();if(id==MONTH){for(String s:monthly(list,YearMonth.from(today)))msgs.add(new Msg("month",s));}else{for(Person person:onDate(list,today.plusDays(offset(c,id))))msgs.add(new Msg("birthdays",personMessage(person,today.plusDays(offset(c,id)),today,false)));if(today.getDayOfWeek()==DayOfWeek.MONDAY&&flag(c,"weekend"))for(int back=2;back>=1;back--){LocalDate day=today.minusDays(back),target=day.plusDays(offset(c,id));for(Person person:onDate(list,target))msgs.add(new Msg("weekend",weekendMessage(person,target,day)));}}
   enqueue(c,msgs,key,value);}
  scheduleOne(c,id);kick(c);
 }
 static List<Person> onDate(List<Person> list,LocalDate d){List<Person> out=new ArrayList<>();for(Person x:list)if(x.ageIn(d.getYear())>=0&&x.birthday(d.getYear()).equals(d))out.add(x);out.sort(Comparator.comparing(Person::name));return out;}
 static String esc(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
 static String bold(String s){return "<b>"+esc(s)+"</b>";}
 static String age(int a){int n=a%100;return a+" "+(n>=11&&n<=14?"років":a%10==1?"рік":a%10>=2&&a%10<=4?"роки":"років");}
 static String date(LocalDate d){return d.getDayOfMonth()+" "+ExportFilter.MONTHS[d.getMonthValue()-1];}
 static String personMessage(Person x,LocalDate d,LocalDate today,boolean repeat){long days=java.time.temporal.ChronoUnit.DAYS.between(today,d);boolean jub=x.jubilee(d.getYear());String when=days==0?"Сьогодні":days==1?"Завтра":days>1?"Через "+days+" "+ReminderReceiver.dayWord((int)days):date(d);String title=(jub?"🎉 ":days==0?"🎂 ":"🔔 ")+when+(jub?" — ювілей!":" — день народження!");String details=(x.job+" · "+x.unit).replaceAll("^ · | · $","");String ageLine=(days==0?"Виповнюється ":days>0?"Виповниться ":"Виповнилося ")+age(x.ageIn(d.getYear()))+(jub?"!":".");return bold(title)+"\n\n"+bold(x.name())+(details.isEmpty()?"":"\n"+esc(details))+"\n\n📅 "+date(d)+"\n"+(jub?"🏅 "+bold(ageLine):esc(ageLine));}
 static String weekendMessage(Person x,LocalDate birthday,LocalDate original){return bold("📢 Повтор за "+(original.getDayOfWeek()==DayOfWeek.SATURDAY?"суботу":"неділю")+" ("+original.format(DATE)+")")+"\n\n"+personMessage(x,birthday,LocalDate.now(),true);}
 static List<String> monthly(List<Person> list,YearMonth month){List<Person> selected=ExportFilter.select(list,month.getYear(),month.getMonthValue(),"",false,0);List<String> out=new ArrayList<>();String header=bold("🎂 Іменинники "+ExportFilter.MONTHS[month.getMonthValue()-1]);StringBuilder s=new StringBuilder(header);int jub=0;for(Person x:selected){boolean j=x.jubilee(month.getYear());if(j)jub++;String line="\n\n"+x.birthday(month.getYear()).format(DATE)+" — "+(j?bold(x.name()+" ("+age(x.ageIn(month.getYear()))+", ювілей)"):esc(x.name()));if(s.length()+line.length()>3400){out.add(s.toString());s=new StringBuilder(header+" (продовження)");}s.append(line);}if(selected.isEmpty())s.append("\n\nІменинників немає.");s.append("\n\n👥 Усього іменинників: ").append(selected.size()).append("\n🏅 Ювілярів: ").append(jub);out.add(s.toString());return out;}
 static List<String> test(Context c,String type){List<Person> list=ReminderReceiver.current(c);LocalDate today=LocalDate.now();List<String> out=new ArrayList<>();if(type.equals("month"))out.addAll(monthly(list,YearMonth.from(today)));else if(type.equals("weekend")){LocalDate sat=today.getDayOfWeek()==DayOfWeek.SUNDAY?today.minusDays(1):today.with(java.time.temporal.TemporalAdjusters.nextOrSame(DayOfWeek.SATURDAY));for(int i=0;i<2;i++){LocalDate day=sat.plusDays(i);for(Person x:onDate(list,day))out.add(weekendMessage(x,day,day));}if(out.isEmpty())out.add(bold("📢 Іменинники за вихідні")+"\n\n"+sat.format(DATE)+"–"+sat.plusDays(1).format(DATE)+": іменинників немає.");}else{for(boolean jub:new boolean[]{false,true}){Person best=null;LocalDate nearest=null;for(Person x:list)for(int y=today.getYear();y<=today.getYear()+6;y++){LocalDate d=x.birthday(y);if(d.isBefore(today)||x.ageIn(y)<0||x.jubilee(y)!=jub)continue;if(nearest==null||d.isBefore(nearest)){best=x;nearest=d;}break;}out.add(best==null?(jub?"Найближчого ювіляра не знайдено.":"Найближчого звичайного іменинника не знайдено."):personMessage(best,nearest,today,false));}}return out;}
 static final class Msg{final String kind,body;Msg(String k,String b){kind=k;body=b;}}
 static JSONArray queue(Context c){try{return new JSONArray(p(c).getString("queue","[]"));}catch(Exception e){return new JSONArray();}}
 static synchronized void enqueue(Context c,List<Msg> msgs,String key,String val){JSONArray a=queue(c);for(Msg m:msgs)try{a.put(new JSONObject().put("id",UUID.randomUUID().toString()).put("kind",m.kind).put("body",m.body));}catch(JSONException ignored){}p(c).edit().putString("queue",a.toString()).putString(key,val).commit();}
 static boolean allowed(Context c,String kind){return connected(c)&&flag(c,"enabled")&&flag(c,kind)&&(!kind.equals("weekend")||flag(c,"birthdays"));}
 static synchronized void prune(Context c){JSONArray a=queue(c),b=new JSONArray();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&allowed(c,x.optString("kind")))b.put(x);}p(c).edit().putString("queue",b.toString()).commit();}
 static synchronized JSONObject peek(Context c){prune(c);return queue(c).optJSONObject(0);}
 static synchronized void remove(Context c,String id){JSONArray a=queue(c),b=new JSONArray();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&!id.equals(x.optString("id")))b.put(x);}p(c).edit().putString("queue",b.toString()).commit();}
 static void kick(Context c){if(queue(c).length()==0)return;JobScheduler j=c.getSystemService(JobScheduler.class);if(j.getPendingJob(JOB)!=null)return;j.schedule(new JobInfo.Builder(JOB,new ComponentName(c,TelegramJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).setBackoffCriteria(60_000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).build());}
 static String encrypt(String token)throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(ALIAS)){KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());gen.generateKey();}Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,ks.getKey(ALIAS,null));return Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(token.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);}
 static String token(Context c)throws Exception{String stored=p(c).getString("secret","");if(stored.isEmpty())return "";String[] a=stored.split(":",2);KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,ks.getKey(ALIAS,null),new GCMParameterSpec(128,Base64.decode(a[0],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(a[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);}
 static void connect(Context c,String token,Group group)throws Exception{String secret=encrypt(token);synchronized(Telegram.class){p(c).edit().putString("secret",secret).putString("chat",group.id).putString("group",group.title).putString("queue","[]").commit();}schedule(c);}
 static void disconnect(Context c){synchronized(Telegram.class){p(c).edit().remove("secret").remove("chat").remove("group").remove("queue").commit();}c.getSystemService(JobScheduler.class).cancel(JOB);schedule(c);}
 static final class Group {final String id,title;Group(String i,String t){id=i;title=t;}}
 static class ApiException extends IOException{final int code;ApiException(int c,String text){super(text);code=c;}}
 static JSONObject api(String token,String method,JSONObject body)throws Exception{if(!token.matches("[0-9]+:[A-Za-z0-9_-]+"))throw new IOException("Перевір токен бота.");HttpURLConnection conn=null;try{conn=(HttpURLConnection)new URL("https://api.telegram.org/bot"+token+"/"+method).openConnection();conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(8000);conn.setReadTimeout(10000);conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json; charset=UTF-8");try(OutputStream os=conn.getOutputStream()){os.write(body.toString().getBytes(StandardCharsets.UTF_8));}int status=conn.getResponseCode();InputStream stream=status>=400?conn.getErrorStream():conn.getInputStream();if(stream==null)throw new IOException("Telegram недоступний.");ByteArrayOutputStream data=new ByteArrayOutputStream();try(InputStream in=stream){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){data.write(buf,0,n);if(data.size()>8_000_000)throw new IOException("Завелика відповідь Telegram.");}}JSONObject result=new JSONObject(data.toString("UTF-8"));if(!result.optBoolean("ok")){int code=result.optInt("error_code",status);throw new ApiException(code,code==401?"Невірний токен бота.":code==403?"Бот не має доступу до групи.":code==409?"Бот використовує webhook або інший клієнт getUpdates.":"Telegram: помилка "+code); }return result;}catch(ApiException e){throw e;}catch(Exception e){throw new IOException("Не вдалося з’єднатися з Telegram. Перевір інтернет і налаштування бота.");}finally{if(conn!=null)conn.disconnect();}}
 static List<Group> discover(String token)throws Exception{api(token,"getMe",new JSONObject());JSONArray updates=api(token,"getUpdates",new JSONObject().put("timeout",0).put("allowed_updates",new JSONArray(Arrays.asList("message","my_chat_member"))).put("limit",100)).getJSONArray("result");Map<String,Group> found=new LinkedHashMap<>();for(int i=0;i<updates.length();i++){JSONObject u=updates.getJSONObject(i);for(String key:new String[]{"message","my_chat_member"}){JSONObject msg=u.optJSONObject(key);if(msg==null)continue;JSONObject chat=msg.optJSONObject("chat");if(chat==null)continue;String type=chat.optString("type");if(type.equals("group")||type.equals("supergroup")){String id=String.valueOf(chat.getLong("id"));found.put(id,new Group(id,chat.optString("title",id)));}}}return new ArrayList<>(found.values());}
 static Group verify(String token,String id)throws Exception{JSONObject chat=api(token,"getChat",new JSONObject().put("chat_id",id)).getJSONObject("result");String type=chat.optString("type");if(!type.equals("group")&&!type.equals("supergroup"))throw new IOException("Потрібна група Telegram.");return new Group(String.valueOf(chat.getLong("id")),chat.optString("title",id));}
 static void send(String token,String chat,String body)throws Exception{api(token,"sendMessage",new JSONObject().put("chat_id",chat).put("text",body).put("parse_mode","HTML"));}
 static void sendTest(Context c,String type)throws Exception{String token,chat;synchronized(Telegram.class){if(!connected(c))throw new IOException("Спочатку підключи групу Telegram.");token=token(c);chat=p(c).getString("chat","");}for(String body:test(c,type))send(token,chat,bold("🧪 ТЕСТОВЕ ПОВІДОМЛЕННЯ")+"\n\n"+body);}
}
